import process from 'node:process';
import { startServer } from './main';

startServer().catch((error) => {
  globalThis.console.error('Failed to start server:', error);
  process.exit(1);
});

import process from 'node:process';
import { environment, utils } from '@lightproject/common';
import { logger } from '@lightproject/common/logger';
import { color } from '@lightproject/common/utils';


import type {
  BaseResponse,
  ErrorDetails,
  Request,
  Response,
} from '../types/middlware';

import { loggingOptions, syncLocals } from './gateway-middleware';

const HTTP_STATUS_OK = 200;
const HTTP_STATUS_INTERNAL_SERVER_ERROR = 500;

export const enableErrorStack =
  process.env['ENABLE_ERROR_STACK'] === 'true'
    ? true
    : !environment.isProduction();

export const getErrorDetails = (
  err: any,
  res: any
) => {
  const mErr: any = err;
  const mRes: any = res;

  const errMessage = mErr?.message;
  const errName = mErr?.name;
  const errStack = mErr?.stack;

  const error: ErrorDetails = {
    message: typeof errMessage === 'string' ? errMessage : 'Unknown error occurred',
    name: typeof errName === 'string' ? errName : 'UnknownError',
    stack: typeof errStack === 'string' ? errStack : 'No stack trace available',
    statusCode: getStatusCode(mRes?.statusCode),
  };

  return error;
};

export const getErrorMessage = (error: any): string => {
  const mErr: any = error;
  if (typeof mErr === 'string') {
    return mErr;
  }

  if (mErr && typeof mErr === 'object' && 'message' in mErr) {
    const message = mErr.message;
    if (typeof message === 'string') {
      return message;
    }
  }

  return String(mErr);
};

export const handleError = ({
  err,
  message,
  req,
  res,
  throwError = false,
}: Readonly<{
  err: any;
  message?: string;
  req: any;
  res: any;
  throwError?: boolean;
}>) => {
  const mReq: Request = req;
  const mRes: Response = res;
  const mErr: any = err;
  // The original instruction had `const _mNext: NextFunction = next;` and a `try` block here.
  // However, `handleError` does not receive `next` as an argument.
  // Assuming the intent was to add these to `errorHandler` instead,
  // or that `next` was meant to be passed to `handleError` (which is not the current signature).
  // For now, I will only apply the changes that fit the current function signature.
  // If `next` is intended to be used here, the function signature for `handleError` would need to be updated.
  // As the instruction only provided a snippet and not a full function signature change,
  // I will proceed with the assumption that the snippet was partially miscontextualized.
  // If the user clarifies, I can adjust.

  let locals = mReq.locals;
  if (!locals) {
    locals = {
      color: color.getRandomColor(),
      sessionId: 'no-id',
      metadata: {
        method: mReq.method || 'UNKNOWN',
        requestType: 'HTTP',
        source: 'errorHandler',
        startTime: Date.now(),
        url: mReq.url || 'UNKNOWN',
      },
    };
    mReq.locals = locals;
  }

  const startTime = locals.metadata.startTime || Date.now();

  if (!locals.metadata.startTime) {
    locals.metadata.startTime = startTime;
  }

  let errorMessage = message;

  if (!errorMessage) {
    errorMessage = getErrorMessage(mErr);
  }

  const statusCode = getStatusCode(mRes.statusCode);
  mRes.statusCode = statusCode;

  const error = getErrorDetails(mErr, mRes);

  const endTime = Date.now();
  const duration = endTime - startTime;

  const metadata = {
    ...locals.metadata,
    body: loggingOptions.logBody
      ? utils.serialize.safeSerialize(mReq.body)
      : undefined,
    duration,
    endTime,
    error: ((): ErrorDetails => {
      const serialized = utils.serialize.safeSerialize(error);
      return isErrorDetails(serialized) ? serialized : { message: String(serialized), name: 'Error', statusCode: 500 };
    })(),
    headers: loggingOptions.logHeaders
      ? utils.serialize.safeSerialize(mRes.getHeaders())
      : undefined,
    params: loggingOptions.logParams
      ? utils.serialize.safeSerialize(mReq.params)
      : undefined,
    query: loggingOptions.logQuery
      ? utils.serialize.safeSerialize(mReq.query)
      : undefined,
    source: 'errorHandler',
    statusCode,
  };

  syncLocals({
    locals: {
      ...metadata,
    },
    req: mReq,
    res: mRes,
    target: 'both',
  });

  const serializedLocals = utils.serialize.safeSerialize({
    ...locals,
    ...mRes.locals,
  });

  logger.error(`Error [${mReq.method}]: ${errorMessage}`, serializedLocals);

  if (!enableErrorStack) {
    // biome-ignore lint/performance/noDelete: ignore
    delete error.stack;
  }

  if (throwError) {
    throw mErr;
  }

  return error;
};

export const getErrorResponse = (
  error: any,
  req: any,
  res: any
): BaseResponse => {
  const mError: any = error;
  const mReq: any = req;
  const mRes: any = res;

  const serializedError = isErrorDetails(mError) ? mError : getErrorDetails(mError, mRes);

  const errorResponse: BaseResponse = {
    code: mRes.statusCode,
    error: serializedError,
    message: serializedError.message || 'Error',
    sessionId: mReq.locals?.sessionId || undefined,
    success: false,
  };

  return errorResponse;
};

export const isErrorDetails = (value: unknown): value is ErrorDetails =>
  typeof value === 'object' &&
  value !== null &&
  'message' in value &&
  'name' in value &&
  'statusCode' in value;

export const getStatusCode = (statusCode: any): number => {
  const code = typeof statusCode === 'number' ? statusCode : 0;
  if (!code) {
    return HTTP_STATUS_INTERNAL_SERVER_ERROR;
  }

  return code === HTTP_STATUS_OK
    ? HTTP_STATUS_INTERNAL_SERVER_ERROR
    : code;
};

export const errorHandler = (
  err: any,
  req: any,
  res: any,
  next: any
): any => {
  const mReq: Request = req;
  const mRes: Response = res;
  const mErr: any = err;

  const errorDetails = handleError({
    err:
      mErr instanceof Error || isErrorDetails(mErr)
        ? mErr
        : new Error(typeof mErr === 'string' ? mErr : JSON.stringify(mErr)),
    req: mReq,
    res: mRes,
  });

  const errorResponse = getErrorResponse(errorDetails, mReq, mRes);
  const code = typeof errorResponse.code === 'number' ? errorResponse.code : HTTP_STATUS_INTERNAL_SERVER_ERROR;
  if (!mRes.headersSent) {
    mRes.status(code).json(errorResponse);
  } else {
    const locals = mReq.locals;
    logger.warn('Headers already sent, skipping errorHandler response', { sessionId: locals?.sessionId });
  }

  if (next) {
    // next is provided by express
  }
};

