import { Buffer } from 'node:buffer';
import type { NextFunction, Response } from '../types/middlware';

const isBufferEncoding = (val: unknown): val is BufferEncoding => {
  const encodings: string[] = ['ascii', 'utf8', 'utf16le', 'ucs2', 'base64', 'latin1', 'binary', 'hex'];
  return typeof val === 'string' && encodings.includes(val);
};

export const captureResponse = (_req: any, res: any, next: any): void => {
  const mRes: Response = res;
  const __mNext: NextFunction = next;

  if (mRes.locals['metadata']) {
    mRes.locals['metadata']['source'] = 'captureResponse';
  }

  const originalWrite: any = mRes.write.bind(mRes);
  const originalEnd: any = mRes.end.bind(mRes);
  const originalSend = mRes.send.bind(mRes);

  const chunks: Buffer[] = [];

  mRes.send = (body: any): Response => {
    if (body) {
      if (typeof body === 'string') {
        chunks.push(Buffer.from(body));
      } else if (Buffer.isBuffer(body)) {
        chunks.push(body);
      } else {
        chunks.push(Buffer.from(JSON.stringify(body)));
      }
    }
    return originalSend(body);
  };

  mRes.write = (
    chunk: any,
    encodingOrCallback?: any,
    callback?: any
  ): boolean => {
    if (chunk) {
      if (typeof chunk === 'string') {
        chunks.push(Buffer.from(chunk, isBufferEncoding(encodingOrCallback) ? encodingOrCallback : 'utf8'));
      } else {
        chunks.push(Buffer.from(chunk));
      }
    }
    if (typeof encodingOrCallback === 'function') {
      return originalWrite(chunk, encodingOrCallback);
    }
    return originalWrite(chunk, encodingOrCallback, callback);
  };

  mRes.end = (
    chunk: any,
    encodingOrCallback?: any,
    callback?: any
  ): Response => {
    if (chunk) {
      if (typeof chunk === 'string') {
        chunks.push(Buffer.from(chunk, isBufferEncoding(encodingOrCallback) ? encodingOrCallback : 'utf8'));
      } else {
        chunks.push(Buffer.from(chunk));
      }
    }

    const fullBody = Buffer.concat(chunks).toString('utf8');
    if (mRes.locals['metadata']) {
      mRes.locals['metadata']['responseBody'] = fullBody;
    }

    if (typeof encodingOrCallback === 'function') {
      return originalEnd(chunk, encodingOrCallback);
    }
    return originalEnd(chunk, encodingOrCallback, callback);
  };

  if (typeof __mNext === 'function') {
    __mNext();
  }
};

import type {
  ExpressNextFunction,
  ExpressResponse,
} from '../types/middlware';

import { allowedOrigins } from '../utils/cors';

export const allowedCsp = [...allowedOrigins];

export const cspMiddleware = (
  _req: any,
  res: any,
  next: any
) => {
  const mRes: ExpressResponse = res;
  const _mNext: ExpressNextFunction = next;

  let csp = '';
  for (const origin of allowedCsp) {
    csp += `default-src 'self'; script-src 'self' ${origin}; worker-src 'self' ${origin}; `;
  }

  csp = csp.trim();

  mRes.setHeader('Content-Security-Policy', csp);

  _mNext();
};

import { utils } from '@lightproject/common';

import type {
  MiddlewareLoggingOptionsType,
  NextFunction,
  Request,
  Response,
} from '../types/middlware';

import { requestHandler } from './request-handler';
import { responseHandler } from './response-handler';

export const loggingOptions: MiddlewareLoggingOptionsType = {
  logBody: false,
  logHeaders: false,
  logParams: false,
  logQuery: false,
};

export const syncLocals = (opts: any): void => {
  const {
    locals,
    req,
    res,
    target = 'both',
  } = opts;

  if (typeof target !== 'string' || !['both', 'req', 'res'].includes(target)) {
    throw new Error('Target must be either "both", "req", or "res"');
  }

  if (!locals) {
    throw new Error('Locals must be provided to sync local variables');
  }

  if (!(req || res)) {
    throw new Error(
      'Either req or res must be provided to sync local variables'
    );
  }

  const allLocals = utils.serialize.safeClone({
    ...(req?.locals ? req.locals : {}),
    ...(res?.locals ? res.locals : {}),
    ...locals,
  });

  if (req && (target === 'req' || target === 'both')) {
    const reqLocals: any = utils.serialize.safeClone(allLocals || {});
    if (reqLocals['originalStatusCode']) {
      // biome-ignore lint/performance/noDelete: ignore
      delete reqLocals['originalStatusCode'];
    }
    if (reqLocals['responseBody']) {
      // biome-ignore lint/performance/noDelete: ignore
      delete reqLocals['responseBody'];
    }
    req.locals = {
      ...req.locals,
      ...reqLocals,
    };
  }

  if (res && (target === 'res' || target === 'both')) {
    const resLocals: any = utils.serialize.safeClone(allLocals || {});
    res.locals = utils.serialize.safeClone({
      ...res.locals,
      ...resLocals,
    });
  }
};

export const gatewayMiddleware = (
  req: any,
  res: any,
  next: any
): void => {
  const mReq: Request = req;
  const mRes: Response = res;
  const _mNext: NextFunction = next;

  // Wrap response first to capture body, then handle request start
  responseHandler(mReq, mRes, () => {
    requestHandler(mReq, mRes, _mNext);
  });
};

import process from 'node:process';
import { endpoints } from '@lightproject/common/configs';
import { isLocal, isTest } from '@lightproject/common/environment';
import { logger } from '@lightproject/common/logger';
import { text } from '@lightproject/common/utils';
import cors from 'cors';
import express from 'express';
// import { cspMiddleware } from './middlewares/csp';
import { errorHandler } from './middlewares/error-handler';
import { gatewayMiddleware } from './middlewares/gateway-middleware';
import { initializeRequest } from './middlewares/initialize-request';
import { notFoundHandler } from './middlewares/not-found-handler';
import { swaggerOpenApiMiddleware } from './middlewares/swagger-openapi';
import { trpcPlayground } from './middlewares/trpc-playground';
import { trustProxyMiddleware } from './middlewares/trust-proxy';
// import { autogen } from './utils/autogen';
import { extractAllRoutes } from './utils/autogen/index';
import { corsOptions } from './utils/cors';
import { registerHttpRoutes } from './utils/http-router';
import { registerTrpcRoutes } from './utils/trpc-router';

const createApp = async () => {
  const app = express();

  app.use(express.json());
  app.use(express.urlencoded({ extended: true }));
  app.use(cors(corsOptions));

  app.use(initializeRequest);
  app.use(gatewayMiddleware);

  app.set('trust proxy', true);
  app.use(trustProxyMiddleware);

  // app.use(cspMiddleware);

  const routes = await extractAllRoutes();

  registerHttpRoutes(app, routes, endpoints.apiEndpoint);
  registerTrpcRoutes(app, endpoints.trpcEndpoint);

  if (isLocal() && !isTest()) {
    trpcPlayground(app, routes).catch(error => {
      logger.error('Failed to initialize tRPC Playground:', error);
    });
    logger.info(`🧪 tRPC Playground: ${endpoints.trpcPlaygroundUrl}`);
    swaggerOpenApiMiddleware(app, routes);
    logger.info(`📚 Swagger UI: ${endpoints.docsUrl}`);
  }

  app.use(notFoundHandler);

  app.use(errorHandler);

  return app;
};

const isRecord = (val: unknown): val is Record<string, unknown> =>
  typeof val === 'object' && val !== null;

const createTestApp = async () => {
  const globe = globalThis as Record<string, unknown>;
  const maybeRequire = globe['require'];

  if (isRecord(maybeRequire)) {
    const cache = maybeRequire['cache'];
    if (isRecord(cache)) {
      for (const key of Object.keys(cache)) {
        if (key.includes('main')) {
          // biome-ignore lint/performance/noDelete: ignore
          delete cache[key];
        }
      }
    }
  }

  return await createApp();
};

const startServer = async () => {
  const app = isLocal() || isTest() ? await createTestApp() : await createApp();

  const defaultPort = 3000;
  const port = process.env['PORT'] || defaultPort;
  const emojiPadding = 3;

  app.listen(port, () => {
    logger.info(
      `${text.padEmoji('🖥️', emojiPadding)} Server is running on http://localhost:${port}`
    );
  });
};

export { createApp, createTestApp, startServer };

import { AsyncLocalStorage } from 'node:async_hooks';
import { randomUUID } from 'node:crypto';
import { endpoints } from '@lightproject/common/configs';
import { color } from '@lightproject/common/utils';
import type { ChalkInstance } from 'chalk';
import cryptoJs from 'crypto-js';

const uuidv4 = () => randomUUID();

import { logger } from '@lightproject/common/logger';

import type {
  Locals,
  NextFunction,
  Request,
  Response,
} from '../types/middlware';

import { syncLocals } from './gateway-middleware';

const asyncLocalStorage = new AsyncLocalStorage();

let previousColor: ChalkInstance | undefined;

export const initializeRequest = (
  req: any,
  res: any,
  next: any
) => {
  const mReq: Request = req;
  const mRes: Response = res;
  const _mNext: NextFunction = next;
  try {
    let locals = mReq.locals;
    if (!locals) {
      locals = {
        color: color.defaultColor,
        sessionId: 'initializing',
        metadata: {
          method: mReq.method,
          requestType: endpoints.getRequestType(mReq.originalUrl || '/'),
          source: 'initializeRequest',
          startTime: Date.now(),
          url: mReq.originalUrl || '/',
        },
      };
      mReq.locals = locals;
    }

    const sessionId = uuidv4();

    const { nextColor, previousColor: newPrevColor } = color.getNextRandomColor(
      cryptoJs.SHA256(sessionId).toString(),
      previousColor ?? color.defaultColor
    );
    locals.color = nextColor;
    previousColor = newPrevColor;

    previousColor = locals.color;

    const updatedLocals: Locals = {
      ...locals,
      metadata: {
        method: mReq.method,
        requestType: endpoints.getRequestType(mReq.originalUrl),
        source: 'initializeRequest',
        startTime: Date.now(),
        url: mReq.originalUrl,
      },
      sessionId,
    };

    syncLocals({
      locals,
      req: mReq,
      target: 'req',
    });

    logger.info(`Initializing [${mReq.method}] request session`, mReq.locals);

    asyncLocalStorage.run(new Map<string, any>([['locals', updatedLocals]]), () => {
      mRes.locals = updatedLocals;
      const resLocals: any = mRes.locals;
      resLocals.originalStatusCode = mRes.statusCode;
      _mNext();
    });
  } catch (error) {
    next(error);
  }
};

const isLocals = (val: unknown): val is Locals =>
  typeof val === 'object' && val !== null && 'sessionId' in val && 'color' in val;

export const getSessionId = () => {
  const store = asyncLocalStorage.getStore();
  if (store instanceof Map) {
    const locals = store.get('locals');
    if (isLocals(locals)) {
      return String(locals.sessionId);
    }
  }
  return 'no-id';
};

export const getColor = () => {
  const store = asyncLocalStorage.getStore();
  if (store instanceof Map) {
    const locals = store.get('locals');
    if (isLocals(locals) && locals.color) {
      return locals.color;
    }
  }
  return color.getRandomColor();
};

export const getLocals = () => {
  const store = asyncLocalStorage.getStore();
  if (store instanceof Map) {
    const locals = store.get('locals');
    if (isLocals(locals)) {
      return locals;
    }
  }
  return { color: color.getRandomColor(), sessionId: 'no-id' };
};

import { getErrorResponse } from './error-handler';
import {
  type ExpressNextFunction,
  type ExpressRequest,
  type ExpressResponse,
  HTTP_STATUS_NOT_FOUND,
} from '../types/middlware';

/**
 * Handles 404 Not Found errors by returning a standard error response.
 * This should be placed after all other routes.
 * 
 * @param req - The Express request object
 * @param res - The Express response object
 * @param next - The Express next function
 */
export const notFoundHandler = (
  req: any,
  res: any,
  next: any
) => {
  const mReq: ExpressRequest = req;
  const mRes: ExpressResponse = res;
  const __mNext: ExpressNextFunction = next;

  mRes.statusCode = HTTP_STATUS_NOT_FOUND;
  const errorResponse = getErrorResponse(
    new Error('Not Found'),
    mReq,
    mRes
  );

  if (!mRes.headersSent) {
    mRes.status(HTTP_STATUS_NOT_FOUND).json(errorResponse);
  }

  if (typeof __mNext === 'function') {
    // Usually not needed for 404 but added for completeness
  }
};

import { logger } from '@lightproject/common/logger';
import type { NextFunction, Request } from '../types/middlware';

export const requestHandler = (
  req: any,
  _res: any,
  next: any
) => {
  const mReq: Request = req;
  const _mNext: NextFunction = next;

  const existingLocals = mReq.locals;
  if (!existingLocals) {
    mReq.locals = {
      metadata: {
        method: mReq.method,
        requestType: 'HTTP',
        startTime: Date.now(),
        url: mReq.url,
      },
      sessionId: 'initializing',
    };
  }

  logger.info(`Request started: ${mReq.method} ${mReq.url}`, mReq.locals);

  if (typeof _mNext === 'function') {
    _mNext();
  }
};

import { Buffer } from 'node:buffer';
import { logger } from '@lightproject/common/logger';
import type { NextFunction, Request, Response } from '../types/middlware';

export const responseHandler = (
  req: any,
  res: any,
  next: any
) => {
  const mReq: Request = req;
  const mRes: Response = res;
  const _mNext: NextFunction = next;

  const originalWrite: any = mRes.write.bind(mRes);
  const originalEnd: any = mRes.end.bind(mRes);

  const chunks: Buffer[] = [];

  mRes.write = (
    chunk: any,
    encodingOrCallback?: any,
    callback?: any
  ): boolean => {
    if (chunk) {
      if (typeof chunk === 'string') {
        chunks.push(Buffer.from(chunk, encodingOrCallback));
      } else {
        chunks.push(Buffer.from(chunk));
      }
    }
    if (typeof encodingOrCallback === 'function') {
      return originalWrite(chunk, encodingOrCallback);
    }
    return originalWrite(chunk, encodingOrCallback, callback);
  };

  mRes.end = (
    chunk: any,
    encodingOrCallback?: any,
    callback?: any
  ): Response => {
    if (chunk) {
      if (typeof chunk === 'string') {
        chunks.push(Buffer.from(chunk, encodingOrCallback));
      } else {
        chunks.push(Buffer.from(chunk));
      }
    }

    const fullBody = Buffer.concat(chunks).toString('utf8');
    const mReqLocals: any = mReq.locals;
    if (mReqLocals.metadata) {
      mReqLocals.metadata['responseBody'] = fullBody;
    }

    logger.info(`Response ended: ${mReq.method} ${mReq.url}`, mReq.locals);

    if (typeof encodingOrCallback === 'function') {
      return originalEnd(chunk, encodingOrCallback);
    }
    return originalEnd(chunk, encodingOrCallback, callback);
  };

  _mNext();
};

