const createContext = (opts: any): ServiceContext => {
  const { req, res } = opts;
  const mReq: Request = req;
  const mRes: Response = res;
  const existingLocals = mReq.locals;
  const sessionId = existingLocals?.sessionId || uuidv4();

  if (!existingLocals || typeof existingLocals !== 'object') {
    mReq.locals = {
      metadata: {
        method: mReq.method,
        requestType: endpoints.getRequestType(mReq.originalUrl),
        startTime: Date.now(),
        url: mReq.originalUrl,
      },
      sessionId,
    };
  }

  if (mReq.locals && !mReq.locals.sessionId) {
    mReq.locals.sessionId = sessionId;
  }

  const ctx: ServiceContext = {
    req: mReq,
    res: mRes,
  };

  return ctx;
};

