/**
 * Extract the HTTP method from initializer text
 */
const extractHttpMethod = (initializer: any): string => {
  if (!initializer) {
    return 'unknown';
  }

  const text = initializer.getText();
  if (text.includes('publicHttp.get')) {
    return 'get';
  }
  if (text.includes('publicHttp.post')) {
    return 'post';
  }
  if (text.includes('publicHttp.put')) {
    return 'put';
  }
  if (text.includes('publicHttp.delete')) {
    return 'delete';
  }
  if (text.includes('publicHttp.patch')) {
    return 'patch';
  }
  return 'unknown';
};

/**
 * Extract route path from property name node
 */
const extractRoutePath = (nameNode: any): string | null => {
  if (!(nameNode instanceof Node)) {
    return null;
  }
  if (Node.isStringLiteral(nameNode)) {
    return nameNode.getLiteralValue();
  }
  if (Node.isIdentifier(nameNode)) {
    return nameNode.getText();
  }
  return null;
};

/**
 * Process routes from an object literal expression
 */
const processRouteProperties = async (
  expression: any,
  handlerFilePath: string
): Promise<readonly RouteInfo[]> => {
  if (!(expression instanceof Node) || !Node.isObjectLiteralExpression(expression)) {
    globalThis.console.warn(`Export is not object literal in ${handlerFilePath}`);
    return [];
  }

  const routePromises = expression.getProperties().map(async (propertyNode: any) => {
    if (!(propertyNode instanceof Node) || !Node.isPropertyAssignment(propertyNode)) {
      return null;
    }
    const property = propertyNode;

    const nameNode = property.getNameNode();
    const routePath = extractRoutePath(nameNode);

    if (!routePath) {
      return null;
    }

    const method = extractHttpMethod(property.getInitializer());
    const serviceClass = getServiceNameFromHandlerFile(handlerFilePath);
    const serviceMethod = extractHttpServiceMethod(handlerFilePath, routePath);

    globalThis.console.log('HTTP service extraction:', {
      handlerFilePath,
      path: routePath,
      serviceClass,
      serviceMethod,
    });

    const { input, serviceFilePath } = await extractServiceMetadata(
      serviceClass,
      serviceMethod
    );

    return {
      handlerFilePath,
      input,
      method,
      output: undefined,
      path: routePath,
      requestType: 'HTTP',
      serviceClass,
      serviceFilePath,
      serviceMethod,
    } as RouteInfo;
  });

  return (await Promise.all(routePromises)).filter(
    (route): route is RouteInfo => route !== null
  );
};

/**
 * Extract all HTTP routes from the HTTP router
 */
export const getHttpRoutes = async (): Promise<RouteInfo[]> => {
  globalThis.console.log('Extracting HTTP routes...');

  const routes: RouteInfo[] = [];
  const project = getProject();
  const httpRouterPath = `${projectDir}/src/routers/http/index.ts`;
  const httpRouterFile = project.getSourceFile(httpRouterPath);

  if (!httpRouterFile) {
    globalThis.console.warn(`HTTP router file not found: ${httpRouterPath}`);
    return routes;
  }

  // Get imported route names from the HTTP router
  const importedRouteNames = httpRouterFile
    .getImportDeclarations()
    .map((importDecl: any) => importDecl.getDefaultImport()?.getText())
    .filter((name: any): name is string => name !== undefined);

  globalThis.console.log('Found HTTP route imports:', importedRouteNames);

  // Process each imported route file
  const filePromises = importedRouteNames.map(async routeName => {
    const handlerFilePath = `${projectDir}/src/routers/http/routes/${routeName.replace('Routes', '').toLowerCase()}.ts`;
    const handlerFile = project.getSourceFile(handlerFilePath);

    if (!handlerFile) {
      globalThis.console.warn(`Handler file not found: ${handlerFilePath}`);
      return [];
    }

    globalThis.console.log(`Processing HTTP routes from: ${handlerFilePath}`);

    const exportAssignment = handlerFile
      .getExportAssignments()
      .find((assignment: any) => !assignment.isExportEquals());

    if (!exportAssignment) {
      globalThis.console.warn(`No default export found in ${handlerFilePath}`);
      return [];
    }

    const localRoutes = await processRouteProperties(
      exportAssignment.getExpression() as Readonly<Node>,
      handlerFilePath
    );
    return localRoutes;
  });

  const allRoutes = await Promise.all(filePromises);
  for (const fileRoutes of allRoutes) {
    routes.push(...fileRoutes);
  }

  return routes;
};

import path from 'node:path';
import { projectDir } from '../config';
import { extractServiceMetadata } from '../parsers/service-parser';
import { extractTrpcRoutesFromFile } from '../parsers/trpc-parser';
import type { RouteInfo } from '../types';

/**
 * Extract all tRPC routes from the tRPC router using AST-based parsing
 */
export const getTrpcRoutes = async (): Promise<RouteInfo[]> => {
  const routes: RouteInfo[] = [];
  const trpcRouterDir = path.resolve(projectDir, 'src/routers/trpc/routes');

  try {
    // Use AST-based parsing to extract routes from all tRPC route files
    const fs = await import('node:fs/promises');
    const routeFiles = await Promise.resolve(fs.readdir(trpcRouterDir));

    const routesArrays = await Promise.all(
      routeFiles.map(async file => {
        if (!file.endsWith('.ts') || file.endsWith('.d.ts')) {
          return [];
        }

        const filePath = path.join(trpcRouterDir, file);

        try {
          // Extract router prefix from filename (e.g., 'test.ts' -> 'test')
          const routerPrefix = path.basename(file, '.ts');

          // Extract routes using enhanced AST-based parser
          const fileRoutes = extractTrpcRoutesFromFile(filePath, routerPrefix);

          // Convert extracted routes to RouteInfo format
          const fileRouteInfos = await Promise.all(
            fileRoutes.map(async route => {
              if (!(route.serviceClass && route.serviceMethod)) {
                globalThis.console.warn(
                  `Skipping route with missing service info: ${route.path}`
                );
                return null;
              }

              // Extract service metadata using shared helper
              const { input: serviceInput, serviceFilePath } =
                await extractServiceMetadata(
                  route.serviceClass,
                  route.serviceMethod
                );

              // Extract procedure type from enhanced parser or default to 'query'
              const type: 'mutation' | 'query' = route.procedureType || 'query';
              const method = type === 'mutation' ? 'post' : 'get';

              return {
                handlerFilePath: filePath,
                input: serviceInput,
                method,
                output: undefined, // TODO: Extract output schema from AST
                path: route.path, // Already includes /trpc/ prefix from enhanced parser
                requestType: 'tRPC',
                serviceClass: route.serviceClass,
                serviceFilePath,
                serviceMethod: route.serviceMethod,
                type,
              } as RouteInfo;
            })
          );

          return fileRouteInfos.filter((r): r is RouteInfo => r !== null);
        } catch (error) {
          globalThis.console.warn(`Failed to parse tRPC routes from ${filePath}:`, error);
          return [];
        }
      })
    );

    routes.push(...routesArrays.flat());
  } catch (error) {
    globalThis.console.warn('Failed to read tRPC routes directory:', error);
    return [];
  }

  return routes;
};

import type { ParameterMetadata } from '@lightproject/common';

import type { RouteInfo } from '../types';

/**
 * OpenAPI operation definition
 */
interface OpenApiOperation {
  readonly description?: string;
  readonly parameters?: readonly OpenApiParameter[];
  readonly requestBody?: {
    readonly content: Readonly<Record<string, { readonly schema: OpenApiSchema }>>;
    readonly required?: boolean;
  };
  readonly responses: Readonly<Record<string, OpenApiResponse>>;
  readonly summary?: string;
  readonly tags?: readonly string[];
}

/**
 * OpenAPI parameter definition
 */
interface OpenApiParameter {
  readonly description?: string;
  readonly in: 'cookie' | 'header' | 'path' | 'query';
  readonly name: string;
  readonly required?: boolean;
  readonly schema: OpenApiSchema;
}

/**
 * OpenAPI response definition
 */
interface OpenApiResponse {
  readonly content?: Readonly<Record<string, { readonly schema: OpenApiSchema }>>;
  readonly description: string;
}

/**
 * OpenAPI schema definition
 */
interface OpenApiSchema {
  readonly allOf?: readonly OpenApiSchema[];
  readonly anyOf?: readonly OpenApiSchema[];
  readonly default?: unknown;
  readonly description?: string;
  readonly example?: unknown;
  readonly format?: string;
  readonly items?: OpenApiSchema;
  readonly oneOf?: readonly OpenApiSchema[];
  readonly properties?: Readonly<Record<string, OpenApiSchema>>;
  readonly required?: readonly string[];
  readonly type?: string;
}

/**
 * Constants for example values
 */
const EXAMPLE_NUMBER_VALUE = 123;
const EXAMPLE_SECOND_NUMBER_VALUE = 456;
const HTTP_STATUS_BAD_REQUEST = 400;
const HTTP_STATUS_INTERNAL_SERVER_ERROR = 500;

/**
 * Example values for OpenAPI schema generation
 */
const EXAMPLE_VALUES = {
  booleanArray: [true, false],
  booleanValue: true,
  httpStatusBadRequest: HTTP_STATUS_BAD_REQUEST,
  httpStatusInternalError: HTTP_STATUS_INTERNAL_SERVER_ERROR,
  numberArray: [EXAMPLE_NUMBER_VALUE, EXAMPLE_SECOND_NUMBER_VALUE],
  numberValue: EXAMPLE_NUMBER_VALUE,
  stringArray: ['ABC', 'DEF'],
  stringValue: 'ABC',
} as const;

/**
 * OpenAPI 3.0 specification structure
 */
interface OpenApiSpec {
  components?: {
    schemas?: Record<string, OpenApiSchema>;
  };
  info: {
    description?: string;
    title: string;
    version: string;
  };
  openapi: string;
  paths: Record<string, Record<string, OpenApiOperation>>;
  servers: Array<{
    description?: string;
    url: string;
  }>;
}

/**
 * Generate OpenAPI 3.0 specification from route information
 */
const generateOpenApiSpec = (
  routes: readonly RouteInfo[],
  options: Readonly<{
    description?: string;
    serverUrl?: string;
    title?: string;
    version?: string;
  }> = {}
): OpenApiSpec => {
  const {
    description = 'Auto-generated API documentation from route discovery',
    serverUrl = 'http://localhost:3000',
    title = 'Pancake API',
    version = '1.0.0',
  } = options;

  const spec: OpenApiSpec = {
    components: {
      schemas: {},
    },
    info: {
      description,
      title,
      version,
    },
    openapi: '3.0.3',
    paths: {},
    servers: [
      {
        description: 'Development server',
        url: serverUrl,
      },
    ],
  };

  // Group routes by path and method
  const pathGroups = groupRoutesByPath(routes);

  // Generate paths
  for (const [path, pathRoutes] of Object.entries(pathGroups)) {
    const pathOps: Record<string, OpenApiOperation> = {};

    for (const route of pathRoutes) {
      const method = (route.method || 'get').toLowerCase();
      pathOps[method] = generateOperation(route);
    }
    spec.paths[path] = pathOps;
  }

  return spec;
};

/**
 * Group routes by normalized path
 */
const groupRoutesByPath = (
  routes: readonly RouteInfo[]
): Record<string, readonly RouteInfo[]> => {
  const groups: Record<string, RouteInfo[]> = {};

  for (const route of routes) {
    // Normalize path - handle empty paths
    let normalizedPath = route.path || '/';

    // Ensure path starts with /
    if (!normalizedPath.startsWith('/')) {
      normalizedPath = `/${normalizedPath}`;
    }

    if (!groups[normalizedPath]) {
      groups[normalizedPath] = [];
    }

    groups[normalizedPath]?.push(route);
  }

  return groups;
};

/**
 * Generate OpenAPI operation from route info
 */
const generateOperation = (route: Readonly<RouteInfo>): OpenApiOperation => {
  const method = (route.method || 'get').toLowerCase();

  const parameters =
    route.input &&
    route.input.length > 0 &&
    ['delete', 'get', 'head'].includes(method)
      ? route.input.map(param => convertToQueryParameter(param))
      : undefined;

  const requestBody =
    route.input &&
    route.input.length > 0 &&
    !['delete', 'get', 'head'].includes(method)
      ? {
          content: {
            'application/json': {
              schema: convertParametersToRequestBodySchema(route.input),
            },
          },
          required: route.input.some(p => p.required),
        }
      : undefined;

  return {
    description: generateOperationDescription(route),
    ...(parameters ? { parameters } : {}),
    ...(requestBody ? { requestBody } : {}),
    responses: generateResponses(route),
    summary: generateOperationSummary(route),
    tags: generateOperationTags(route),
  };
};

/**
 * Generate operation summary
 */
const generateOperationSummary = (route: Readonly<RouteInfo>): string => {
  const serviceName = route.serviceClass?.replace('Service', '') || 'Unknown';
  const methodName = route.serviceMethod || 'unknown';

  if (route.requestType === 'tRPC') {
    const procedureType = route.type === 'mutation' ? 'Mutation' : 'Query';
    return `${serviceName} ${methodName} (${procedureType})`;
  }

  return `${serviceName} ${methodName}`;
};

/**
 * Generate operation description with enhanced context
 */
const generateOperationDescription = (route: Readonly<RouteInfo>): string => {
  // Try to generate a more descriptive description based on method patterns
  const enhancedDescription = generateMethodDescription(
    route.serviceMethod,
    route.serviceClass
  );

  if (enhancedDescription) {
    return enhancedDescription;
  }

  // Fallback to basic description
  const parts: string[] = [];

  if (route.serviceClass && route.serviceMethod) {
    parts.push(`Calls ${route.serviceClass}.${route.serviceMethod}()`);
  }

  if (route.requestType === 'tRPC') {
    parts.push(`tRPC ${route.type || 'query'} procedure`);
  } else {
    parts.push('HTTP endpoint');
  }

  return parts.join(' - ');
};

/**
 * Generate enhanced method description based on method name and service class
 */
const generateMethodDescription = (
  methodName?: string,
  serviceClass?: string
): string | undefined => {
  if (!(methodName && serviceClass)) {
    return undefined;
  }

  const service = serviceClass.replace('Service', '');

  // Method prefix lengths for resource extraction
  const GetPrefixLength = 3; // "get".length
  const CreateAddPrefixLength = 6; // "create".length, "add".length
  const UpdateEditPrefixLength = 6; // "update".length, "edit".length
  const DeleteRemovePrefixLength = 6; // "delete".length, "remove".length

  // Handle common method patterns
  if (methodName === 'root') {
    return `Get ${service} service status and basic information`;
  }

  if (methodName.startsWith('get')) {
    const resource = methodName.slice(GetPrefixLength);
    return `Retrieve ${resource.toLowerCase()} data from ${service}`;
  }

  if (methodName.startsWith('create') || methodName.startsWith('add')) {
    const resource = methodName.slice(CreateAddPrefixLength);
    return `Create new ${resource.toLowerCase()} in ${service}`;
  }

  if (methodName.startsWith('update') || methodName.startsWith('edit')) {
    const resource = methodName.slice(UpdateEditPrefixLength);
    return `Update existing ${resource.toLowerCase()} in ${service}`;
  }

  if (methodName.startsWith('delete') || methodName.startsWith('remove')) {
    const resource = methodName.slice(DeleteRemovePrefixLength);
    return `Delete ${resource.toLowerCase()} from ${service}`;
  }

  if (methodName.includes('Success')) {
    return `Execute ${methodName.replace('Success', '')} operation successfully`;
  }

  if (methodName.includes('Fail')) {
    return `Simulate ${methodName.replace('Fail', '')} operation failure for testing`;
  }

  if (methodName.startsWith('hello')) {
    return 'Generate personalized greeting message';
  }

  if (methodName.includes('Params')) {
    return 'Test and validate various parameter types and structures';
  }

  if (methodName === 'mixedParams') {
    return 'Process mixed parameter types including primitives, objects, and arrays';
  }

  if (methodName === 'objectOnly') {
    return 'Process object-only parameters with optional properties';
  }

  if (methodName === 'objectDestructured') {
    return 'Process destructured object parameters';
  }

  if (methodName === 'primitivesAndArray') {
    return 'Process primitive parameters and array data';
  }

  return undefined; // Let the caller use fallback description
};

/**
 * Generate operation tags
 */
const generateOperationTags = (route: Readonly<RouteInfo>): readonly string[] => {
  const tags: string[] = [];

  // Add service-based tag
  if (route.serviceClass) {
    tags.push(route.serviceClass.replace('Service', ''));
  }

  // Add request type tag
  tags.push(route.requestType);

  return tags;
};

/**
 * Generate responses for the operation with enhanced schemas
 */
const generateResponses = (
  route: Readonly<RouteInfo>
): Record<string, OpenApiResponse> => {
  const successSchema = generateEnhancedResponseSchema(route.serviceMethod);

  return {
    '200': {
      content: {
        'application/json': {
          schema: successSchema,
        },
      },
      description: 'Successful response',
    },
    '400': {
      content: {
        'application/json': {
          schema: {
            properties: {
              error: {
                description: 'Error message',
                type: 'string',
              },
              statusCode: {
                description: 'HTTP status code',
                example: EXAMPLE_VALUES.httpStatusBadRequest,
                type: 'number',
              },
            },
            required: ['error', 'statusCode'],
            type: 'object',
          },
        },
      },
      description: 'Bad request - Invalid input parameters',
    },
    '500': {
      content: {
        'application/json': {
          schema: {
            properties: {
              error: {
                description: 'Internal error message',
                type: 'string',
              },
              statusCode: {
                description: 'HTTP status code',
                example: EXAMPLE_VALUES.httpStatusInternalError,
                type: 'number',
              },
            },
            required: ['error', 'statusCode'],
            type: 'object',
          },
        },
      },
      description: 'Internal server error',
    },
  };
};

/**
 * Generate enhanced response schema based on method patterns
 */
const generateEnhancedResponseSchema = (methodName?: string): OpenApiSchema => {
  if (!methodName) {
    return getDefaultResponseSchema();
  }

  // Pattern-based response schemas
  if (methodName === 'root') {
    return {
      properties: {
        message: {
          description: 'Service status message',
          example: 'OK',
          type: 'string',
        },
      },
      required: ['message'],
      type: 'object',
    };
  }

  if (methodName.includes('Success')) {
    return {
      properties: {
        message: {
          description: 'Success confirmation message',
          example: 'Operation completed successfully',
          type: 'string',
        },
      },
      required: ['message'],
      type: 'object',
    };
  }

  if (methodName.startsWith('hello')) {
    return {
      properties: {
        message: {
          description: 'Personalized greeting message',
          example: 'Hello, John Doe!',
          type: 'string',
        },
      },
      required: ['message'],
      type: 'object',
    };
  }

  if (
    methodName.includes('Params') ||
    methodName === 'mixedParams' ||
    methodName === 'objectOnly' ||
    methodName === 'objectDestructured' ||
    methodName === 'primitivesAndArray'
  ) {
    return {
      properties: {
        data: {
          description: 'Processed input parameters and their values',
          properties: {
            // This would be dynamically generated based on input parameters
          },
          type: 'object',
        },
        message: {
          description: 'Processing confirmation message',
          example: 'Parameters processed successfully',
          type: 'string',
        },
      },
      required: ['message'],
      type: 'object',
    };
  }

  if (methodName === '_checkParams') {
    return {
      properties: {
        booleanArrayOutput: {
          example: EXAMPLE_VALUES.booleanArray,
          items: { type: 'boolean' },
          type: 'array',
        },
        booleanOutput: {
          example: EXAMPLE_VALUES.booleanValue,
          type: 'boolean',
        },
        numberArrayOutput: {
          example: EXAMPLE_VALUES.numberArray,
          items: { type: 'number' },
          type: 'array',
        },
        numberOutput: {
          example: EXAMPLE_VALUES.numberValue,
          type: 'number',
        },
        objectBooleanArrayOutput: {
          properties: {
            booleanArray: {
              items: { type: 'boolean' },
              type: 'array',
            },
          },
          type: 'object',
        },
        objectBooleanOutput: {
          properties: {
            boolean: { type: 'boolean' },
          },
          type: 'object',
        },
        objectMultipleOutput: {
          description: 'Complex nested object with multiple data types',
          type: 'object',
        },
        objectNumberArrayOutput: {
          properties: {
            numberArray: {
              items: { type: 'number' },
              type: 'array',
            },
          },
          type: 'object',
        },
        objectNumberOutput: {
          properties: {
            number: { type: 'number' },
          },
          type: 'object',
        },
        objectStringArrayOutput: {
          properties: {
            stringArray: {
              items: { type: 'string' },
              type: 'array',
            },
          },
          type: 'object',
        },
        objectStringOutput: {
          properties: {
            string: { type: 'string' },
          },
          type: 'object',
        },
        stringArrayOutput: {
          example: EXAMPLE_VALUES.stringArray,
          items: { type: 'string' },
          type: 'array',
        },
        stringOutput: {
          example: EXAMPLE_VALUES.stringValue,
          type: 'string',
        },
      },
      type: 'object',
    };
  }

  // Default enhanced response
  return getDefaultResponseSchema();
};

/**
 * Get default response schema with enhanced structure
 */
const getDefaultResponseSchema = (): OpenApiSchema => {
  return {
    properties: {
      data: {
        description: 'Response data payload',
        type: 'object',
      },
      message: {
        description: 'Response message',
        type: 'string',
      },
      success: {
        description: 'Operation success indicator',
        type: 'boolean',
      },
    },
    type: 'object',
  };
};

/**
 * Convert parameter metadata to query parameter
 */
const convertToQueryParameter = (
  param: Readonly<ParameterMetadata>
): OpenApiParameter => {
  return {
    in: 'query',
    name: param.name,
    required: param.required,
    schema: convertTypeToSchema(param.type, param.defaultValue),
  };
};

/**
 * Convert parameters to request body schema
 */
const convertParametersToRequestBodySchema = (
  params: readonly ParameterMetadata[]
): OpenApiSchema => {
  const properties: Record<string, OpenApiSchema> = {};
  const requiredFields: string[] = [];

  for (const param of params) {
    properties[param.name] = convertTypeToSchema(
      param.type,
      param.defaultValue
    );

    if (param.required) {
      requiredFields.push(param.name);
    }
  }

  return {
    properties,
    ...(requiredFields.length > 0 ? { required: requiredFields } : {}),
    type: 'object',
  };
};

/**
 * Convert TypeScript type string to OpenAPI schema
 */
const convertTypeToSchema = (
  type: string,
  defaultValue?: unknown
): OpenApiSchema => {
  const schema: any = {};

  if (defaultValue !== undefined) {
    schema.default = defaultValue;
  }

  // Handle array types
  if (type.endsWith('[]')) {
    const itemType = type.slice(0, -2);
    return {
      default: defaultValue,
      items: convertTypeToSchema(itemType),
      type: 'array',
    };
  }

  // Handle union types (e.g., "string | undefined")
  if (type.includes(' | ')) {
    const unionTypes = type.split(' | ').map(t => t.trim());
    const nonUndefinedTypes = unionTypes.filter(t => t !== 'undefined');

    if (nonUndefinedTypes.length === 1) {
      const [singleType] = nonUndefinedTypes;
      if (singleType) {
        return convertTypeToSchema(singleType, defaultValue);
      }
    }

    return {
      default: defaultValue,
      oneOf: nonUndefinedTypes.map(t => convertTypeToSchema(t)),
    };
  }

  // Handle object types
  if (type.startsWith('{') && type.endsWith('}')) {
    return convertObjectTypeToSchema(type, defaultValue);
  }

  // Handle primitive types
  switch (type) {
    case 'any':
    case 'unknown': {
      return { default: defaultValue, description: 'Any value' };
    }
    case 'boolean': {
      return { default: defaultValue, type: 'boolean' };
    }
    case 'number': {
      return { default: defaultValue, type: 'number' };
    }
    case 'string': {
      return { default: defaultValue, type: 'string' };
    }
    default: {
      return {
        default: defaultValue,
        description: `Type: ${type}`,
        type: 'string',
      };
    }
  }
};

/**
 * Convert object type string to OpenAPI schema
 * Handles types like "{ foo: string; bar?: number; }"
 */
const convertObjectTypeToSchema = (
  type: string,
  defaultValue?: unknown
): OpenApiSchema => {
  const schema: OpenApiSchema = {
    default: defaultValue,
    properties: {},
    type: 'object',
  };

  // Simple parsing of object type - this could be enhanced with proper TypeScript AST parsing
  const content = type.slice(1, -1).trim(); // Remove { }

  if (!content) {
    return schema;
  }

  const required: string[] = [];
  const properties: Record<string, OpenApiSchema> = {};

  // Split by semicolon but handle nested objects
  const props = parseObjectProperties(content);

  for (const prop of props) {
    const colonIndex = prop.indexOf(':');
    if (colonIndex === -1) {
      continue;
    }

    const propName = prop.slice(0, colonIndex).trim();
    const propType = prop.slice(colonIndex + 1).trim();

    const isOptional = propName.endsWith('?');
    const cleanPropName = isOptional ? propName.slice(0, -1).trim() : propName;

    properties[cleanPropName] = convertTypeToSchema(propType);

    if (!isOptional) {
      required.push(cleanPropName);
    }
  }

  return {
    ...schema,
    properties,
    ...(required.length > 0 ? { required } : {}),
  } as OpenApiSchema;
};

/**
 * Parse object properties handling nested braces
 */
const parseObjectProperties = (content: string): string[] => {
  const properties: string[] = [];
  let current = '';
  let braceDepth = 0;

  for (const char of content) {
    if (char === '{') {
      braceDepth++;
    } else if (char === '}') {
      braceDepth--;
    } else if (char === ';' && braceDepth === 0) {
      if (current.trim()) {
        properties.push(current.trim());
      }
      current = '';
      continue;
    }

    current += char;
  }

  // Add the last property if it doesn't end with semicolon
  if (current.trim()) {
    properties.push(current.trim());
  }

  return properties;
};

