import { Project } from 'ts-morph';

/**
 * Cache configuration constants
 */
const CACHE_VALIDITY_MINUTES = 5;
const SECONDS_PER_MINUTE = 60;
const MILLISECONDS_PER_SECOND = 1000;
const MINUTES_TO_MS = SECONDS_PER_MINUTE * MILLISECONDS_PER_SECOND;
const BYTES_TO_KB = 1024;

/**
 * Cache for ts-morph Project instances to avoid recreating them
 */
class ProjectCache {
  private readonly cacheValidityMs: number =
    CACHE_VALIDITY_MINUTES * MINUTES_TO_MS;
  private lastCacheTime = 0;
  private projectCache: Project | undefined;

  /**
   * Clear the project cache to free memory
   */
  clearCache(): void {
    this.projectCache = undefined;
    this.lastCacheTime = 0;
  }

  /**
   * Get cache statistics
   */
  getCacheStats(): {
    cacheAge: number;
    cached: boolean;
    validFor: number;
  } {
    const now = Date.now();
    const cacheAge = now - this.lastCacheTime;
    const validFor = Math.max(0, this.cacheValidityMs - cacheAge);

    return {
      cacheAge,
      cached: Boolean(this.projectCache),
      validFor,
    };
  }

  /**
   * Get or create a cached ts-morph Project instance
   */
  getProject(): Project {
    const now = Date.now();

    // Check if we have a valid cached project
    if (this.projectCache && now - this.lastCacheTime < this.cacheValidityMs) {
      return this.projectCache;
    }

    // Create new project with optimized settings
    this.projectCache = new Project({
      // Only load what we need for better performance
      skipAddingFilesFromTsConfig: false,
      skipFileDependencyResolution: true,
      skipLoadingLibFiles: true,
      tsConfigFilePath: 'tsconfig.json',
      useInMemoryFileSystem: false,
    });

    this.lastCacheTime = now;
    return this.projectCache;
  }
}

/**
 * File parsing cache to avoid re-parsing the same files
 */
class FileParsingCache {
  private readonly fileCache: Map<string, { content: string; mtime: number }> =
    new Map();

  /**
   * Cache file content with its modification time
   */
  cacheFile(filePath: string, content: string, mtime: number): void {
    this.fileCache.set(filePath, { content, mtime });
  }

  /**
   * Clear the file cache
   */
  clearCache(): void {
    this.fileCache.clear();
  }

  /**
   * Get cached file content
   */
  getCachedContent(filePath: string): string | undefined {
    return this.fileCache.get(filePath)?.content;
  }

  /**
   * Get cache statistics
   */
  getCacheStats(): {
    cachedFiles: number;
    totalSizeKb: number;
  } {
    let totalSize = 0;
    for (const { content } of this.fileCache.values()) {
      totalSize += content.length;
    }

    return {
      cachedFiles: this.fileCache.size,
      totalSizeKb: Math.round(totalSize / BYTES_TO_KB),
    };
  }

  /**
   * Check if a file needs to be re-parsed based on modification time
   */
  needsUpdate(filePath: string, currentMtime: number): boolean {
    const cached = this.fileCache.get(filePath);
    return !cached || cached.mtime < currentMtime;
  }
}

/**
 * Global cache instances
 */
export const projectCache = new ProjectCache();
export const fileParsingCache = new FileParsingCache();

import { performance } from 'node:perf_hooks';
import { logger } from '@lightproject/common/logger';

// Constants for formatting and display
const SEPARATOR_LENGTH = 50;
const PROGRESS_BAR_LENGTH = 20;
const LOG_INTERVAL_MS = 500;
const SECONDS_THRESHOLD_MS = 1000;
const PERCENTAGE_DECIMAL_PLACES = 1;
const DURATION_DECIMAL_PLACES = 2;
const PERCENTAGE_MULTIPLIER = 100;
const OPERATION_NAME_PADDING = 25;
const DURATION_PADDING = 8;

/**
 * Performance measurement utility for autogen operations
 */
export class PerformanceTimer {
  private readonly measurements: Map<string, number> = new Map();
  private readonly operations: Array<{ duration: number; name: string }> = [];
  private startTime = 0;

  /**
   * Get the total elapsed time since start
   */
  getTotal(): number {
    return performance.now() - this.startTime;
  }

  /**
   * Mark the start of a specific operation
   */
  mark(operationName: string): void {
    this.measurements.set(operationName, performance.now());
  }

  /**
   * End timing for a specific operation and log progress
   */
  measure(operationName: string, showProgress = true): number {
    const startTime = this.measurements.get(operationName);
    if (!startTime) {
      logger.warn(`No start time found for operation: ${operationName}`);
      return 0;
    }

    const duration = performance.now() - startTime;
    this.operations.push({ duration, name: operationName });

    if (showProgress) {
      const formattedDuration = this.formatDuration(duration);
      logger.info(`✅ ${operationName} completed in ${formattedDuration}`);
    }

    return duration;
  }

  /**
   * Show a detailed performance summary
   */
  showSummary(): void {
    const totalTime = this.getTotal();
    const formattedTotal = this.formatDuration(totalTime);

    logger.info(`\n📊 Performance Summary (Total: ${formattedTotal})`);
    logger.info('='.repeat(SEPARATOR_LENGTH));

    // Sort operations by duration (longest first)
    const sortedOps = this.operations.toSorted(
      (a: any, b: any) => b.duration - a.duration
    );

    for (const op of sortedOps) {
      const formattedDuration = this.formatDuration(op.duration);
      const percentage = (
        (op.duration / totalTime) *
        PERCENTAGE_MULTIPLIER
      ).toFixed(PERCENTAGE_DECIMAL_PLACES);
      logger.info(
        `  ${op.name.padEnd(OPERATION_NAME_PADDING)} ${formattedDuration.padStart(DURATION_PADDING)} (${percentage}%)`
      );
    }

    logger.info('='.repeat(SEPARATOR_LENGTH));
  }

  /**
   * Start timing the overall process
   */
  start(): void {
    this.startTime = performance.now();
    this.measurements.clear();
    this.operations.length = 0;
  }

  /**
   * Format duration in human-readable format
   */
  private formatDuration(ms: number): string {
    return ms < SECONDS_THRESHOLD_MS
      ? `${ms.toFixed(0)}ms`
      : `${(ms / SECONDS_THRESHOLD_MS).toFixed(DURATION_DECIMAL_PLACES)}s`;
  }
}

/**
 * Progress indicator for operations with known counts
 */
export class ProgressIndicator {
  private current = 0;
  private lastLogTime = 0;
  private readonly logInterval: number = LOG_INTERVAL_MS; // Log every 500ms
  private readonly operation: string;
  private readonly total: number;

  constructor(operation: string, total: number) {
    this.operation = operation;
    this.total = total;
  }

  /**
   * Complete the progress indicator
   */
  complete(): void {
    this.current = this.total;
    this.logProgress();
  }

  /**
   * Update progress and optionally log
   */
  update(increment = 1): void {
    this.current += increment;

    const now = performance.now();
    if (
      now - this.lastLogTime > this.logInterval ||
      this.current === this.total
    ) {
      this.logProgress();
      this.lastLogTime = now;
    }
  }

  /**
   * Create a simple progress bar
   */
  private createProgressBar(percentage: number): string {
    const barLength = PROGRESS_BAR_LENGTH;
    const filled = Math.round((percentage / PERCENTAGE_MULTIPLIER) * barLength);
    const empty = barLength - filled;
    return `[${'█'.repeat(filled)}${' '.repeat(empty)}]`;
  }

  /**
   * Log current progress
   */
  private logProgress(): void {
    const percentage = Math.round(
      (this.current / this.total) * PERCENTAGE_MULTIPLIER
    );
    const bar = this.createProgressBar(percentage);
    logger.info(
      `🔄 ${this.operation}: ${bar} ${this.current}/${this.total} (${percentage}%)`
    );
  }
}

